import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

interface VendorBody {
  id: string;
  status: string;
  submitted_at: string | null;
}

interface DocumentBody {
  id: string;
  status: string;
}

interface ExtractionBody {
  id: string;
  document_id: string;
  kind: string;
  status: string;
}

interface ReviewQueueItemBody {
  vendor_id: string;
  vendor_name: string;
  extractions: ExtractionBody[];
}

interface AuditEventBody {
  id: number;
  action: string;
}

interface AuditTrailBody {
  items: AuditEventBody[];
}

// Unique per run so parallel tests sharing one database don't collide.
function uniqueVendorName(): string {
  return `REV05 Vendor ${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function createSubmittedVendorWithDocuments(member: APIRequestContext): Promise<VendorBody> {
  const created = await member.post("/api/vendors", {
    data: {
      name: uniqueVendorName(),
      category: "software",
      contact_email: `rev05-${Date.now()}-${Math.random().toString(36).slice(2, 6)}@example.test`,
    },
  });
  const vendor = await expectStatus<VendorBody>(created, 201);

  for (const kind of ["w9", "insurance_certificate", "contract"] as const) {
    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind,
        file: {
          name: `${kind}.pdf`,
          mimeType: "application/pdf",
          buffer: Buffer.from("%PDF-1.4 REV-05 test document"),
        },
      },
    });
    await expectStatus<DocumentBody>(upload, 201);
  }

  const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
  const body = await expectStatus<VendorBody>(submitted, 200);
  expect(body.status).toBe("in_review");
  return body;
}

async function waitForVendorExtractions(
  reviewer: APIRequestContext,
  vendorId: string,
): Promise<ExtractionBody[]> {
  let extractions: ExtractionBody[] = [];
  await expect
    .poll(
      async () => {
        const response = await reviewer.get("/api/review-queue");
        const items = await expectStatus<ReviewQueueItemBody[]>(response, 200);
        const item = items.find((i) => i.vendor_id === vendorId);
        extractions = item?.extractions ?? [];
        return extractions.length;
      },
      { timeout: 90_000, intervals: [500, 1000, 2000] },
    )
    .toBe(3);
  return extractions;
}

test(
  "approving every extraction approves the vendor",
  { tag: "@REV-05" },
  async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");
    const vendor = await createSubmittedVendorWithDocuments(member);
    const extractions = await waitForVendorExtractions(reviewer, vendor.id);

    expect(extractions).toHaveLength(3);
    for (const extraction of extractions) {
      expect(extraction.status).toBe("pending_review");
    }

    // Act
    for (const extraction of extractions) {
      const decision = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
        data: { decision: "approve", note: "REV-05 approval" },
      });
      const decided = await expectStatus<ExtractionBody>(decision, 200);
      expect(decided.status).toBe("approved");
    }

    // Assert
    const vendorResponse = await reviewer.get(`/api/vendors/${vendor.id}`);
    const current = await expectStatus<VendorBody>(vendorResponse, 200);
    expect(current.status).toBe("approved");

    const auditResponse = await reviewer.get(`/api/vendors/${vendor.id}/audit`);
    const trail = await expectStatus<AuditTrailBody>(auditResponse, 200);
    expect(trail.items.map((e) => e.action)).toContain("vendor.approved");
  },
);
